          P("无中生有", "选项内容在原文找不到任何依据（哪怕看似合理）。判断方法：给选项每个信息点找原文出处，找不到即排除。"),
          P("绝对化陷阱", "「都、必须、一定、唯一、所有、任何」出现时高度警惕，回原文核对是否有同等表述。原文「多数」「往往」类留有余地的表述，被选项绝对化即为错。"),
