          "【怎么做】代词用就近原则，词语看上下文，句子看前后解释关系；答案必须回到原文找依据。\n"
          "【口诀】代词往前找，词语看语境。\n"
          "【易错】脱离语境套用词典义或常识义；代词指代找到更远的位置。",
