          P("隐含态度判断", "无明确引导词时，从选词的感情色彩判断：全文用褒义词=支持倾向；反讽引号（所谓的「创新」）=否定倾向。"),
          P("引用观点区分", "「有人认为/有专家指出/传统观点认为」是作者引用来对比或批驳的对象，多非作者立场——作者的态度常在引用之后（「但实际上…」）。"),
          P("未表态选项", "文段纯客观说明（介绍一项技术/报道一个事实）无任何倾向词时，大胆选「作者未表明态度」。这是被多数考生回避的正确答案。"),
