          P("反对关系辨析", "上反对：「所有是」与「所有不是」不能同真可同假 → 必有一假；下反对：「有的是」与「有的不是」不能同假可同真 → 必有一真。与矛盾（必一真一假）严格区分。"),
          P("假设法兜底", "无矛盾时假设某句为真/假代入验证冲突；「只有一真」类从最特殊句开始假设。假设不成立→反向即真。"),
