          P("搭桥法", "论据说 A、论点说 B，两者跳跃 → 答案=A 与 B 的连接句（A→B 或「A 是 B 的关键」）。识别标志：论据与论点关键词完全不同。"),
          P("补论据与前提", "无跳跃时补新论据（新例子/数据/权威结论）。前提型问「必需假设」→ 否定代入检验：选项否定后论点崩塌即为必要前提。"),
