# ============================ 题型分类树（tree_type=qtype，轻量） ============================
QTYPES = [
    M("言语理解", "题型分类", [C("题型", "", [P("逻辑填空", ""), P("片段阅读", ""), P("语句表达", ""), P("篇章阅读", "")])]),
    M("判断推理", "题型分类", [C("题型", "", [P("图形推理", ""), P("定义判断", ""), P("类比推理", ""), P("逻辑判断", "")])]),
    M("资料分析", "题型分类", [C("题型", "", [P("文字资料", ""), P("统计表", ""), P("统计图", ""), P("综合资料", "")])]),
    M("数量关系", "题型分类", [C("题型", "", [P("数学运算", ""), P("数字推理", "")])]),
    M("常识判断", "题型分类", [C("题型", "", [P("政治理论", ""), P("法律常识", ""), P("人文历史", ""), P("科技地理", "")])]),
    M("申论", "题型分类", [C("题型", "", [P("归纳概括", ""), P("综合分析", ""), P("提出对策", ""), P("应用文写作", ""), P("文章写作", "")])]),
    M("面试", "题型分类", [C("题型", "", [P("综合分析", ""), P("组织规划", ""), P("应急应变", ""), P("人际关系", ""), P("语言表达", "")])]),
]


def _walk(items, parent_id, teacher_id, ks, created, parent_name="",
          tree_type="knowledge", depth=0):
    """按结构建树（同名同名层级跳过；--force 模式下树已清空，全建）。
    category：模块=「模块」，章节=模块名，知识点=章节名，考点=知识点名。
    description：全部入库（修复批次21 漏传 bug）。"""
    for node in items:
        name = node["name"]
        existing = ks.find_child(teacher_id, parent_id, name, tree_type=tree_type)
        if existing:
            node_id = existing["node_id"]
            created["skip"] += 1
        else:
            if depth == 0:
                cat = "模块"
            elif depth == 1:
                cat = parent_name
            else:
                cat = parent_name  # 知识点=章节名；考点=知识点名（parent_name 即父名）
            # 批次24：考点层（depth==3）追加【例题】文本块（仅 knowledge 树，qtype 的 P 不参与）
            desc = node.get("desc") or ""
            if depth == 3 and tree_type == "knowledge":
                ex = EXAMPLES.get(name)
                if ex:
                    desc = (desc + "\n" + ex) if desc else ex
                    created["ex"] = created.get("ex", 0) + 1
            node_id = ks.create_node(teacher_id, name, parent_id=parent_id,
                                     category=cat,
                                     description=desc,
                                     tree_type=tree_type)["node_id"]
            created["new"] += 1
        _walk(node.get("children") or [], node_id, teacher_id, ks, created, name,
              tree_type, depth + 1)


def build(force=False):
    ks: KnowledgeStore = get_knowledge_store()
    stats = {}
    trees = (YULUN, PANDUAN, ZILIAO, SHULIANG, CHANGSHI, SHENLUN, MIANSHI)
    for tid in ("T001", "T002"):
        if force:
            for tree_type in ("knowledge", "qtype"):
                deleted = _delete_tree(ks, tid, tree_type)
                stats[f"{tid}:{tree_type}:deleted"] = deleted
        c = {"new": 0, "skip": 0}
        for tree in trees:
            _walk([tree], "", tid, ks, c)
        stats[f"{tid}:knowledge"] = c
        qc = {"new": 0, "skip": 0}
        _walk(QTYPES, "", tid, ks, qc, tree_type="qtype")
        stats[f"{tid}:qtype"] = qc
    return stats


def _delete_tree(ks, teacher_id, tree_type):
    """整树删除：从顶层模块起按子树批量删（subtree_ids 含自身）。"""
    n = 0
    for root in ks.get_tree(teacher_id, "", tree_type)["nodes"]:
        ids = ks.subtree_ids(teacher_id, root["node_id"])
        if ids:
            ks.batch_delete(ids)
            n += len(ids)
    return n


def _collect_points(items, names):
    """收集主树全部考点名（depth==3 的 P 节点名）。"""
    for node in items:
        if node.get("children"):
            _collect_points(node["children"], names)
        else:
            names.append(node["name"])


def check_examples():
    """批次24 校验：EXAMPLES 与主树考点名一一对应（不缺不余）。"""
    names = []
    for tree in (YULUN, PANDUAN, ZILIAO, SHULIANG, CHANGSHI, SHENLUN, MIANSHI):
        _collect_points([tree], names)
    missing = [n for n in names if n not in EXAMPLES]
    extra = [k for k in EXAMPLES if k not in names]
    print(f"[check] 主树考点 {len(names)} 个 | EXAMPLES {len(EXAMPLES)} 条 | 缺 {len(missing)} | 多余 {len(extra)}")
    if missing:
        print("  缺例题:", ", ".join(missing))
    if extra:
        print("  多余键:", ", ".join(extra))
    return not missing and not extra


if __name__ == "__main__":
    force = "--force" in sys.argv
    if "--check" in sys.argv:
        raise SystemExit(0 if check_examples() else 1)
    stats = build(force=force)
    print("seed done:", stats)
    for tid in ("T001", "T002"):
        t = get_knowledge_store().get_tree(tid, "", "knowledge")
        q = get_knowledge_store().get_tree(tid, "", "qtype")
        print(f"{tid}: knowledge total={t['total']} top={len(t['nodes'])} | qtype total={q['total']} top={len(q['nodes'])}")
